fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // Pre-calculate maxsplit + 1 as usize for split count parameter
    let max_splits = maxsplit as usize;

    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                // No splitting; output a vector with the original string only
                vec![s]
            } else if s.is_empty() {
                // Empty string results in a single empty string in vector
                vec![String::new()]
            } else {
                // Split from right with at most max_splits splits, resulting in max_splits+1 parts
                // rsplitn returns iterator of &str slices from the right.
                // Collect into a vector of Strings in left-to-right order.
                s.rsplitn(max_splits + 1, &sep)
                    .map(|part| part.to_string())
                    .collect::<Vec<String>>()
                    // Note: rsplitn returns parts in order from right side, so parts are as desired
            }
        })
        .collect()
}